// Osmosis Mainnet configuration for QUARK protocol.
// All denoms generated by this protocol are Token Factory assets on osmosis-1.

// Overridable the same way as DEFAULT_RPC/DEFAULT_LCD below, so pointing
// OSMO_RPC_URL/OSMO_LCD_URL at a testnet (e.g. osmo-test-5) and setting this
// alongside them is enough to redirect Keplr's chain-suggestion metadata
// too — without it, connectKeplr() would claim "osmosis-1" while actually
// talking to a testnet RPC/LCD, which Keplr rejects as inconsistent.
export const OSMO_CHAIN_ID =
  (typeof process !== "undefined" && process.env?.OSMO_CHAIN_ID) ||
  (typeof import.meta !== "undefined" && (import.meta as any).env?.VITE_OSMO_CHAIN_ID) ||
  "osmosis-1";
export const OSMO_CHAIN_NAME =
  (typeof process !== "undefined" && process.env?.OSMO_CHAIN_NAME) ||
  (typeof import.meta !== "undefined" && (import.meta as any).env?.VITE_OSMO_CHAIN_NAME) ||
  "Osmosis";

// Public fallback. For production set OSMO_RPC_URL / OSMO_LCD_URL env vars
// to a paid endpoint (Polkachu, Numia, QuickNode, etc.) — public endpoints
// are rate-limited and unreliable for signing traffic.
export const DEFAULT_RPC =
  (typeof process !== "undefined" && process.env?.OSMO_RPC_URL) ||
  (typeof import.meta !== "undefined" && (import.meta as any).env?.VITE_OSMO_RPC_URL) ||
  "https://rpc.osmosis.zone";

export const DEFAULT_LCD =
  (typeof process !== "undefined" && process.env?.OSMO_LCD_URL) ||
  (typeof import.meta !== "undefined" && (import.meta as any).env?.VITE_OSMO_LCD_URL) ||
  "https://lcd.osmosis.zone";

export const GAS_PRICE = "0.05uosmo";
export const NATIVE_DENOM = "uosmo";
export const NATIVE_EXPONENT = 6;

// Token Factory denom creation fee on osmosis-1 mainnet (NON-REFUNDABLE).
export const TOKENFACTORY_CREATE_DENOM_FEE_UOSMO = 10_000_000; // 10 OSMO

// GAMM classic pool creation fee on osmosis-1 mainnet.
export const GAMM_POOL_CREATE_FEE_UOSMO = 1_000_000_000; // 1000 OSMO

// Minimum native OSMO balance required before attempting a mint/send
// broadcast. Real gas for a single MsgMint/MsgSend is roughly 0.001-0.01
// OSMO; this threshold is a generous buffer so a pre-flight check catches
// "treasury needs funding" before a broadcast attempt, not during one.
export const MIN_GAS_BALANCE_OSMO = 0.5;

export interface KeplrChainInfo {
  chainId: string;
  chainName: string;
  rpc: string;
  rest: string;
  bip44: { coinType: number };
  bech32Config: {
    bech32PrefixAccAddr: string;
    bech32PrefixAccPub: string;
    bech32PrefixValAddr: string;
    bech32PrefixValPub: string;
    bech32PrefixConsAddr: string;
    bech32PrefixConsPub: string;
  };
  currencies: Array<{ coinDenom: string; coinMinimalDenom: string; coinDecimals: number }>;
  feeCurrencies: Array<{
    coinDenom: string;
    coinMinimalDenom: string;
    coinDecimals: number;
    gasPriceStep?: { low: number; average: number; high: number };
  }>;
  stakeCurrency: { coinDenom: string; coinMinimalDenom: string; coinDecimals: number };
}

export function getOsmosisKeplrChainInfo(): KeplrChainInfo {
  return {
    chainId: OSMO_CHAIN_ID,
    chainName: OSMO_CHAIN_NAME,
    rpc: DEFAULT_RPC,
    rest: DEFAULT_LCD,
    bip44: { coinType: 118 },
    bech32Config: {
      bech32PrefixAccAddr: "osmo",
      bech32PrefixAccPub: "osmopub",
      bech32PrefixValAddr: "osmovaloper",
      bech32PrefixValPub: "osmovaloperpub",
      bech32PrefixConsAddr: "osmovalcons",
      bech32PrefixConsPub: "osmovalconspub",
    },
    currencies: [{ coinDenom: "OSMO", coinMinimalDenom: NATIVE_DENOM, coinDecimals: NATIVE_EXPONENT }],
    feeCurrencies: [
      {
        coinDenom: "OSMO",
        coinMinimalDenom: NATIVE_DENOM,
        coinDecimals: NATIVE_EXPONENT,
        gasPriceStep: { low: 0.0025, average: 0.025, high: 0.04 },
      },
    ],
    stakeCurrency: { coinDenom: "OSMO", coinMinimalDenom: NATIVE_DENOM, coinDecimals: NATIVE_EXPONENT },
  };
}
